style.css:
/* Moichiro Runner — Every Website */
/* i really want this to be global */

:root {
    --my-runner-width: 126px;
    --my-runner-height: 90px;
    --my-runner-scale: 0.4;
}

/* custom running character */
.ytp-scrubber-button {
    background-image: url("https://www.deviantart.com/michelstgamer/art/GIF---moichiro-JUS-RUNNING-826574441") !important;
    background-repeat: no-repeat !important;
    background-size: contain !important;
    width: var(--my-runner-width) !important;
    height: var(--my-runner-height) !important;
    margin-left: -75px !important;
    margin-top: -67px !important;
    transform: scale(var(--my-runner-scale)) !important;
}
